// ---- session ---------------------------------------------------------------------------------

// Each sign-in gets its own browser context, so users on one sheet act independently. A context
// is closed once the test that opened it has finished: the test runner leaves them open, and a
// whole suite of open pages, each still running the app, would exhaust the machine.
const opened = new Map<BrowserContext, string>();   // context -> id of the test that opened it

export async function userPage(browser: Browser, user: string, sheet: string): Promise<Page> {
  let owner = '';
  try { owner = test.info().testId; } catch { /* outside a test: nothing to tidy by */ }
  for (const [c, t] of opened) {
    if (t === owner) continue;
    opened.delete(c);
    await c.close().catch(() => { /* already gone */ });
  }
  const context = await browser.newContext();
  opened.set(context, owner);
  const page = await context.newPage();
  page.setDefaultTimeout(LOAD_WAIT);     // an element an action needs that never shows fails here, not at the test's limit
  await page.goto('/');
  await page.getByTestId('signin-name').fill(user);
  await page.getByTestId('signin-submit').click();
  await expect(page.getByTestId('current-user')).toHaveText(user, { timeout: LOAD_WAIT });
  await loadSheet(page, sheet);
  return page;
}

export async function loadSheet(page: Page, sheet: string): Promise<void> {
  await page.getByTestId('sheet-id-input').fill(sheet);
  await page.getByTestId('sheet-load').click();
  await expect(page.getByTestId('sheet-current-id')).toHaveText(sheet, { timeout: LOAD_WAIT });
}

/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
 *  again is not observable (the current id already reads that), so the screen first loads a
 *  throwaway id, which has no one on it, and waits for the person rows to go; then it loads the
 *  sheet again and waits for rows to show. Rows that were on screen before may rightly not come
 *  back (someone retired since, say), so the wait is for any row, and for every row that is back
 *  to carry at least the claims it had; if none shows within the wait the screen is taken as it
 *  is and the test's own checks decide. The show-retired box and the as-of date, which belong to
 *  the screen, are put back if the loads reset them. */
export async function refresh(page: Page): Promise<void> {
  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
  const before = new Map<string, number>();
  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
  const retired = page.getByTestId('show-retired');
  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
  const asofWas = await shown(page.getByTestId('sheet-asof'));
  const previewWas = await shown(page.getByTestId('sheet-preview'));
  await loadSheet(page, sheet + '-reload');
  await expect.poll(() => rows(page).count(), { message: 'the throwaway sheet, which has no one on it, is on screen', timeout: LOAD_WAIT }).toBe(0);
  await loadSheet(page, sheet);
  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
  if (previewWas !== '' && (await shown(page.getByTestId('sheet-preview'))) !== previewWas) await setPreview(page, previewWas);
  if (before.size === 0) return;
  const back = async () => {
    if ((await rows(page).count()) === 0) return false;
    for (const [id, n] of before) {
      const r = row(page, id);
      if ((await r.count()) > 0 && (await claimRows(r).count()) < n) return false;
    }
    return true;
  };
  const deadline = Date.now() + LOAD_WAIT;
  while (Date.now() < deadline && !(await back())) await page.waitForTimeout(50);
#!/usr/bin/env bash
# Build the whole app into ONE runnable jar: the Maven build compiles the front-end
# (frontend-maven-plugin) into src/main/resources/static, then packages the Spring Boot app
# (spring-boot repackage, main net.officefloor.hq.app.Application) into target/*.jar.
set -euo pipefail
cd "$(dirname "$0")/.."

# `clean` first so removed sources (e.g. a deleted route .yml or class) can't linger in
# target/classes and get baked into the jar.
exec ./mvnw -q -DskipTests clean package
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

# Refuse to run against a server that is not ours: an app left running on $PORT (an earlier
# bin/start that was never stopped, another sandbox) would take the tests and fail them all.
if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then
  echo "bin/e2e: something is already serving on port ${PORT}; stop it (bin/stop) or set PORT to a free port" >&2
  exit 2
fi

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL. A loaded
# machine can take minutes to bring the JVM up; running the specs before it is ready fails every
# one of them for no reason, so wait long and fail loudly rather than run against nothing.
ready=0
for i in $(seq 1 300); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
if [ "$ready" != 1 ]; then
  echo "bin/e2e: the app did not become healthy on port ${PORT} within 300s; see .run/app.log" >&2
  exit 2
fi

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
#!/usr/bin/env bash
# Start the Spring Boot app on $PORT (main class net.officefloor.hq.app.Application). On boot, Flyway
# migrates the empty in-memory H2 up to the current schema; Spring serves the SPA (static/) and the
# app's REST endpoints. Returns once
# launching; poll /actuator/health for readiness.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p .run

: "${PORT:?PORT must be set}"
JAR="$(ls -t target/*.jar 2>/dev/null | head -n1 || true)"
[ -n "$JAR" ] || { echo "no jar in target/ — run bin/build first" >&2; exit 1; }

# Known audit file (the file-based test-assertion channel). Absolute so app + tests agree.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

nohup java -jar "$JAR" --server.port="$PORT" --spring.profiles.active=e2e > .run/app.log 2>&1 &
echo $! > .run/app.pid
#!/usr/bin/env bash
# Stop the app and free $PORT. Kills the JVM (in-memory H2 dies with it = clean reset).
# IDEMPOTENT: exit 0 whether or not anything was running.
set -uo pipefail
cd "$(dirname "$0")/.."

if [ -f .run/app.pid ]; then
  kill "$(cat .run/app.pid)" 2>/dev/null || true
  rm -f .run/app.pid
fi
# Backstop: free the port if something is still bound (needs fuser; ignore if absent).
[ -n "${PORT:-}" ] && fuser -k "${PORT}/tcp" 2>/dev/null || true
exit 0
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideRouter } from '@angular/router';
import { routes } from './app.routes';

// The app's wiring: the router and the HTTP client.
export const appConfig: ApplicationConfig = {
  providers: [provideBrowserGlobalErrorListeners(), provideRouter(routes), provideHttpClient()],
};
import { Routes } from '@angular/router';

// The route table. A page is a new component file registered here with one entry that lazily
// imports it; an entry's `data: { section, label }` is read by the shell to build the nav bar.
export const routes: Routes = [
  { path: '', redirectTo: 'home', pathMatch: 'full' },
  {
    path: 'home',
    data: { section: 'home', label: 'Home', order: 0 },
    loadComponent: () => import('./features/home/home').then((m) => m.Home),
  },
];
import { Component, inject } from '@angular/core';
import { Route, Router, RouterLink, RouterOutlet } from '@angular/router';

// Minimal base shell. It renders the nav bar and the routed page. The nav comes from the ROUTER'S
// OWN CONFIG — every route carrying `data.section` becomes a link — so the shell holds no list of
// pages and is not edited when one is added. Every observable element carries a stable data-testid.
@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink],
  template: `
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        @for (r of nav; track r.path) {
          <a
            [routerLink]="'/' + r.path"
            [attr.data-testid]="'nav-' + r.data!['section']"
            >{{ r.data!['label'] }}</a
          >
        }
      </nav>
      <main data-testid="app-home">
        <router-outlet />
      </main>
    </div>
  `,
})
export class App {
  protected readonly nav: Route[] = inject(Router)
    .config.filter((r) => !!r.data?.['section'])
    .sort(
      (a, b) =>
        ((a.data?.['order'] as number) ?? 0) - ((b.data?.['order'] as number) ?? 0) ||
        String(a.data?.['section']).localeCompare(String(b.data?.['section'])),
    );
}
import { Component } from '@angular/core';

// The base home page (empty). A page is an Angular component like this one, plus one entry in
// app.routes.ts.
@Component({
  selector: 'app-home',
  template: `<p data-testid="home-empty">Nothing here yet.</p>`,
})
export class Home {}
package net.officefloor.hq.app;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Spring Boot host: serves the SPA from static/, with H2 + Flyway (schema migrated on boot) and
 * Actuator. Domain REST endpoints, @Service/@Repository beans and migrations are added under
 * src/main/java and src/main/resources.
 */
@SpringBootApplication
public class Application {
    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}
